  <body>
    <main>
      <section class="support-card" aria-labelledby="support-title">
        <p class="eyebrow">Support</p>
        <h1 id="support-title">Contact our team</h1>
        <p class="intro">Tell us how to reach you and a support specialist will follow up with the next steps.</p>
        <div id="app"></div>
      </section>
    </main>

    <script>
      const fields = [
        {
          id: "fullName",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          placeholder: "Alex Morgan",
          required: true,
          validate: (value) => value.trim() ? "" : "Full name is required."
        },
        {
          id: "email",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          placeholder: "alex@example.com",
          required: true,
          validate: (value) => {
            const trimmed = value.trim();
            if (!trimmed) return "Email address is required.";
            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed) ? "" : "Enter a valid email address.";
          }
        },
        {
          id: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          placeholder: "(555) 123-4567",
          required: false,
          helperText: "Optional. Use 10 digits, such as (555) 123-4567.",
          validate: (value) => {
            const trimmed = value.trim();
            if (!trimmed) return "";
            return /^\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}$/.test(trimmed)
              ? ""
              : "Enter a phone number in the format (555) 123-4567.";
          }
        }
      ];

      const state = {
        values: Object.fromEntries(fields.map((field) => [field.id, ""])),
        errors: Object.fromEntries(fields.map((field) => [field.id, ""])),
        submitted: false
      };

      function Field({ field }) {
        const errorId = `${field.id}-error`;
        const helperId = `${field.id}-helper`;
        const describedBy = [field.helperText ? helperId : "", errorId].filter(Boolean).join(" ");
        const error = state.errors[field.id];

        return `
          <div class="form-field">
            <label for="${field.id}">
              ${field.label}
              ${field.required ? '<span class="required-note">(required)</span>' : '<span class="required-note">(optional)</span>'}
            </label>
            <input
              id="${field.id}"
              name="${field.id}"
              type="${field.type}"
              autocomplete="${field.autocomplete}"
              placeholder="${field.placeholder}"
              value="${state.values[field.id]}"
              ${field.required ? "required" : ""}
              aria-required="${field.required ? "true" : "false"}"
              aria-invalid="${error ? "true" : "false"}"
              aria-describedby="${describedBy}"
            >
            ${field.helperText ? `<p class="helper-text" id="${helperId}">${field.helperText}</p>` : ""}
            <p class="error-message" id="${errorId}" aria-live="polite">${error}</p>
          </div>
        `;
      }

      function ContactForm() {
        return `
          <form id="support-form" novalidate>
            ${fields.map((field) => Field({ field })).join("")}
            <p class="success-message" id="form-status" aria-live="polite">
              ${state.submitted ? "Thanks. Your support request details are ready to send." : ""}
            </p>
            <button type="submit">Submit request</button>
          </form>
        `;
      }

      function render() {
        document.getElementById("app").innerHTML = ContactForm();

        fields.forEach((field) => {
          document.getElementById(field.id).addEventListener("input", (event) => {
            state.values[field.id] = event.target.value;
            state.errors[field.id] = field.validate(event.target.value);
            state.submitted = false;
            render();
            document.getElementById(field.id).focus();
          });
        });

        document.getElementById("support-form").addEventListener("submit", (event) => {
          event.preventDefault();
          state.errors = Object.fromEntries(fields.map((field) => [field.id, field.validate(state.values[field.id])]));
          state.submitted = Object.values(state.errors).every((message) => !message);
          render();

          const firstInvalidField = fields.find((field) => state.errors[field.id]);
          document.getElementById(firstInvalidField ? firstInvalidField.id : "form-status").focus?.();
        });
      }

      render();
    </script>
  </body>
</html>
