        width: min(100%, 42rem);
      }

      .support-card {
        padding: clamp(1.5rem, 4vw, 2.5rem);
        border: 1px solid var(--border);
        border-radius: 1.5rem;
        background: rgba(17, 24, 39, 0.88);
        box-shadow: 0 1.5rem 4rem var(--shadow);
        backdrop-filter: blur(18px);
      }

      .eyebrow {
        margin: 0 0 0.5rem;
        color: var(--accent);
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3rem);
        line-height: 1.05;
      }

      .intro {
        margin: 1rem 0 2rem;
        color: var(--muted);
        font-size: 1.05rem;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        gap: 0.45rem;
      }

      label {
        font-weight: 700;
      }

      .required-note {
        color: var(--muted);
        font-weight: 500;
      }

      input {
        width: 100%;
        min-height: 3.25rem;
        border: 1px solid var(--border);
        border-radius: 0.9rem;
        padding: 0.9rem 1rem;
